use super::*;
fn storage_path(raw:&str,bucket:&str)->Result<String,String>{let public=format!("{SUPABASE_URL}/storage/v1/object/public/{bucket}/");let authenticated=format!("{SUPABASE_URL}/storage/v1/object/authenticated/{bucket}/");let path=raw.strip_prefix(public.as_str()).or_else(||raw.strip_prefix(authenticated.as_str())).unwrap_or(raw);let parts:Vec<_>=path.split('/').collect();if parts.len()!=2||parts[0].is_empty()||parts[1].is_empty()||path.len()>300||path.contains("..")||!parts[0].chars().all(|c|c.is_ascii_alphanumeric()||c=='-')||!parts[1].chars().all(|c|c.is_ascii_alphanumeric()||"._-".contains(c)){return Err("Esta imagem não está disponível para salvar.".into())}Ok(path.into())}
fn image_extension(bytes:&[u8])->Option<&'static str>{if bytes.starts_with(&[137,80,78,71,13,10,26,10]){Some("png")}else if bytes.starts_with(&[255,216,255]){Some("jpg")}else if bytes.len()>=12&&bytes.starts_with(b"RIFF")&&&bytes[8..12]==b"WEBP"{Some("webp")}else{None}}
#[tauri::command]
pub async fn save_chat_image(app:AppHandle,message_id:String,group:bool,state:tauri::State<'_,AppState>)->Result<Value,String>{
 let session=current(&state).await?;let id=safe_id(&message_id)?;let table=if group{"clt_chat_group_messages"}else{"clt_chat_messages"};let field=if group{"midia_path"}else{"midia_url"};let bucket=if group{"group-chat-media"}else{"chat-media"};
 let rows=get(&state.client,&format!("/rest/v1/{table}?select={field}&id=eq.{id}&limit=1"),&session.access_token).await?;let raw=rows.as_array().and_then(|r|r.first()).and_then(|r|r[field].as_str()).ok_or("Imagem indisponível nesta conversa.")?;let path=storage_path(raw,bucket)?;
 let client=reqwest::Client::builder().timeout(Duration::from_secs(25)).redirect(reqwest::redirect::Policy::none()).build().map_err(|_|"Não foi possível abrir a imagem.".to_string())?;
 let mut response=client.get(format!("{SUPABASE_URL}/storage/v1/object/authenticated/{bucket}/{path}")).header("apikey",SUPABASE_KEY).bearer_auth(&session.access_token).send().await.map_err(|_|"Não foi possível baixar a imagem.".to_string())?;if !response.status().is_success(){return Err("Não foi possível baixar a imagem.".into())}
 let mut bytes=Vec::new();while let Some(chunk)=response.chunk().await.map_err(|_|"O download foi interrompido.".to_string())?{if bytes.len()+chunk.len()>5*1024*1024{return Err("A imagem excede o limite de 5 MB.".into())}bytes.extend_from_slice(&chunk)}let ext=image_extension(&bytes).ok_or("Formato de imagem inválido.")?;if current(&state).await?.user.id!=session.user.id{return Err("Sua sessão mudou.".into())}
 let downloads=app.path().download_dir().map_err(|_|"Pasta Downloads indisponível.")?;std::fs::create_dir_all(&downloads).map_err(|_|"Pasta Downloads indisponível.")?;let name=format!("BatCaverna-imagem-{}.{ext}",SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos());let target=downloads.join(&name);let mut file=std::fs::OpenOptions::new().write(true).create_new(true).open(&target).map_err(|_|"Não foi possível criar o arquivo em Downloads.".to_string())?;use std::io::Write;if file.write_all(&bytes).is_err(){drop(file);let _=std::fs::remove_file(&target);return Err("Não foi possível salvar a imagem.".into())}Ok(json!({"name":name}))
}
#[cfg(test)]mod tests{use super::*;#[test]fn only_storage_paths_are_accepted(){assert_eq!(storage_path("owner/image.webp","chat-media").unwrap(),"owner/image.webp");for bad in ["../secret","owner/a?token=x","https://other.test/a.png","owner/a/b.png","owner/%2e%2e.png"]{assert!(storage_path(bad,"chat-media").is_err())}}#[test]fn only_known_image_headers_choose_an_extension(){assert_eq!(image_extension(&[137,80,78,71,13,10,26,10]),Some("png"));assert_eq!(image_extension(&[255,216,255,0]),Some("jpg"));assert_eq!(image_extension(b"RIFF1234WEBPpayload"),Some("webp"));assert_eq!(image_extension(b"<html>"),None);}}
